import Foundation

/// The app icons a supporter can choose from — the thank-you for recurring support.
///
/// Every icon but `classic` is an alternate icon in `Resources/AppIcons` (`AppIcon-<Name>`),
/// with a small `IconPreview-<Name>` image for the picker, since app icons can't be loaded
/// as images. Both are generated by `AppIcon/make_icons.py`.
enum SupporterIcon: String, CaseIterable, Identifiable, Sendable {
    case classic = "Default"
    case amethyst = "Amethyst"
    case blush = "Blush"
    case ember = "Ember"
    case glacier = "Glacier"
    case lagoon = "Lagoon"
    case midnightGold = "MidnightGold"
    case noir = "Noir"

    var id: String { rawValue }

    /// The name `UIApplication.setAlternateIconName` takes; `nil` for the primary icon.
    var alternateIconName: String? {
        self == .classic ? nil : "AppIcon-\(rawValue)"
    }

    var previewImageName: String { "IconPreview-\(rawValue)" }

    /// The icon set as the app's icon, given `UIApplication.alternateIconName`.
    init(alternateIconName: String?) {
        self = Self.allCases.first { $0.alternateIconName == alternateIconName } ?? .classic
    }

    var title: LocalizedStringResource {
        switch self {
        case .classic: "support.iconClassic"
        case .amethyst: "support.iconAmethyst"
        case .blush: "support.iconBlush"
        case .ember: "support.iconEmber"
        case .glacier: "support.iconGlacier"
        case .lagoon: "support.iconLagoon"
        case .midnightGold: "support.iconMidnightGold"
        case .noir: "support.iconNoir"
        }
    }
}
